const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const nodes=new Map();function node(){return {children:[],dataset:{},handlers:{},addEventListener(event,fn){this.handlers[event]=fn},replaceChildren(){this.children=[]},append(...x){this.children.push(...x)},value:''}}
const get=id=>{if(!nodes.has(id))nodes.set(id,node());return nodes.get(id)};
const requests=[];
const sandbox={document:{getElementById:get,createElement:node,querySelectorAll:()=>[]},location:{hash:'',pathname:'/onboard/'},history:{replaceState(){}},fetch:async(url,options)=>{requests.push({url,body:JSON.parse(options.body)});return {ok:false,status:401,json:async()=>({error:'expired'})}},setInterval(){},setTimeout(){},navigator:{clipboard:{writeText:async()=>{}}}};
vm.createContext(sandbox);vm.runInContext(fs.readFileSync(process.argv[2],'utf8'),sandbox);
const text=id=>get(id).children.map(n=>n.textContent).join(' ');
sandbox.payload={terminal_only:true,device:{os:'windows',name:'Test',paused:false,activity:{}},network:{mode:'auto'},tunnel:{running:true,local_ready:true,ready:true,cloud_state:'offline',error:'tunnel_network_error',proxy_source:'system'},plugin:{devices_seen:false},codex:{capabilities:{}}};
vm.runInContext('renderState(payload)',sandbox);
assert.doesNotMatch(get('connection').textContent,/已连接|已启用/,'local readiness must not imply cloud connection');
assert.match(text('validation'),/本地服务 就绪/);
assert.match(text('validation'),/云端隧道.*网络/);
assert.match(text('validation'),/源 Dot.*等待/);
assert.match(get('network-summary').textContent,/系统代理/);
sandbox.payload.tunnel={running:true,local_ready:true,ready:true,cloud_state:'online',last_successful_poll_at:'2026-10-13T00:00:00Z',proxy_source:'environment'};
vm.runInContext('renderState(payload)',sandbox);
assert.match(get('connection').textContent,/云端已连接/);
assert.match(text('validation'),/源 Dot.*等待/,'cloud evidence cannot stand in for source-tool invocation');
sandbox.payload.tunnel.cloud_state='backpressured';
sandbox.payload.tunnel.network_change_pending=true;
vm.runInContext('renderState(payload)',sandbox);
assert.match(text('validation'),/已连接，正在处理积压请求/);
assert.match(get('network-summary').textContent,/等待隧道下次启动/);
sandbox.payload.tunnel={running:true,local_ready:true,ready:false,cloud_state:'unconfirmed',proxy_source:'direct'};
vm.runInContext('renderState(payload)',sandbox);
assert.match(text('validation'),/连接未确认/);
get('network-mode').value='manual';get('network-proxy').value='http://127.0.0.1:8118';
get('network-form').handlers.input();
vm.runInContext('renderState(payload)',sandbox);
assert.equal(get('network-mode').value,'manual','refresh overwrote edited network mode');
assert.equal(get('network-proxy').value,'http://127.0.0.1:8118');
console.log('Truthful cloud state and local network form checks passed');
